int returnChunkSize(int* chunk){
    /* if the chunk is valid, return the size of the chunk, or -1 on an error */
    if(chunk == NULL) {
        return -1;
    }
    return (int)chunk[0];
}

int returnSum(int* chunk){
    /* if the chunk is valid, return the sum of the elements in the chunk, or -1 on an error */
    if(chunk == NULL) {
        return -1;
    }
    int sum = 0;
    int i;
    for(i = 0; i < returnChunkSize(chunk); i++) {
        sum += chunk[i];
    }
    return sum;
}

int main(int argc, char *argv[]) {
    int *chunk = NULL;
    int size = 0;
    int i;

    /* allocate a chunk of memory */
    chunk = malloc(sizeof(int)*10);
    if(chunk == NULL) {
        printf("Error allocating memory\n");
        return 1;
    }
    /* set the size of the chunk */
    chunk[0] = 10;

    /* set the elements of the chunk */
    for(i = 0; i < returnChunkSize(chunk); i++) {
        chunk[i] = i;
    }

    /* print the sum of the elements in the chunk */
    printf("%d\n", returnSum(chunk));

    // free the memory
    free(chunk);

    return 0;
}
