        exit(EXIT_FAILURE);
    }
    if (write(pipefd[1], "important_config", strlen("important_config")) == -1) {
        perror("write");
        exit(EXIT_FAILURE);
    }
    if (close(fd) == -1) {
        perror("close");
        exit(EXIT_FAILURE);
    }

    // read the important config from the pipe
    fd = open(important_config, O_RDONLY);
    if (fd == -1) {
        perror("open");
