## 2.2.4. 字符串的替换

字符串的替换是替换字符串中指定的子字符串。

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    const char* message = "Hello, World!";
    const char* search = "World";
    const char* replace = "Earth";

    // replace the search string with the replace string
    char* result = strstr(message, search);
    if (result!= NULL) {
        size_t length = strlen(result);
        size_t replace_length = strlen(replace);
        size_t new_length = length + replace_length;
        char* new_message = malloc(new_length + 1);
        memcpy(new_message, message, length);
        memcpy(new_message + length, replace, replace_length);
        new_message[new_length] = '\0';
        free(message);
        message = new_message;
    }

    // print the message
    printf("%s\n", message);

    return 0;
}
```

