    const char* search = "llo";

    // search for the string
    char* position = strstr(message, search);

    // print the result
    if (position!= NULL) {
        printf("The string '%s' is found at position %d.\n", search, position - message);
    } else {
        printf("The string '%s' is not found.\n", search);
    }

    return 0;
}
```

