```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    const char* message = "Hello world";
    const char* search = "world";
    const char* replace = "universe";

    // replace the string in the message
    char* result = strstr(message, search);
    if (result!= NULL) {
        size_t length = strlen(replace);
        result = strndup(result, length);
